import { mkdirSync, writeFileSync } from "node:fs";

// The inbound ringtone (design.md §9.4), generated rather than sourced so the bundled asset
// carries no third-party license and can be regenerated byte-for-byte. It is the classic
// precise ring tone: 440 Hz + 480 Hz, 2 s on, 4 s off. Keeping the whole 6 s cadence inside
// the file means the offscreen document only has to set `loop` — no timers, no Web Audio.
//
// 8 kHz mono is deliberate: both partials sit far below Nyquist, the sines are generated
// band-limited so nothing aliases, and it holds the asset near 94 KB instead of half a
// megabyte. WAV rather than a compressed format because encoder padding makes MP3 loops gap.

const SAMPLE_RATE = 8000;
const PARTIALS = [440, 480];
const TONE_S = 2;
const SILENCE_S = 4;
// Two partials at this amplitude peak at 0.6 of full scale — audible headroom, no clipping.
const AMPLITUDE = 0.3;
// Without an envelope the burst starts and ends mid-cycle, which clicks on every loop.
const RAMP_S = 0.01;

function renderPcm() {
  const total = Math.round((TONE_S + SILENCE_S) * SAMPLE_RATE);
  const toneSamples = Math.round(TONE_S * SAMPLE_RATE);
  const pcm = Buffer.alloc(total * 2); // silence is zeroed for free
  for (let i = 0; i < toneSamples; i++) {
    const t = i / SAMPLE_RATE;
    const gain = Math.min(1, t / RAMP_S, (TONE_S - t) / RAMP_S);
    const sample = PARTIALS.reduce((sum, hz) => sum + Math.sin(2 * Math.PI * hz * t), 0) * AMPLITUDE * gain;
    pcm.writeInt16LE(Math.round(Math.max(-1, Math.min(1, sample)) * 32767), i * 2);
  }
  return pcm;
}

function wav(pcm) {
  const header = Buffer.alloc(44);
  header.write("RIFF", 0);
  header.writeUInt32LE(36 + pcm.length, 4);
  header.write("WAVE", 8);
  header.write("fmt ", 12);
  header.writeUInt32LE(16, 16); // PCM fmt chunk size
  header.writeUInt16LE(1, 20); // format: PCM
  header.writeUInt16LE(1, 22); // channels: mono
  header.writeUInt32LE(SAMPLE_RATE, 24);
  header.writeUInt32LE(SAMPLE_RATE * 2, 28); // byte rate
  header.writeUInt16LE(2, 32); // block align
  header.writeUInt16LE(16, 34); // bits per sample
  header.write("data", 36);
  header.writeUInt32LE(pcm.length, 40);
  return Buffer.concat([header, pcm]);
}

mkdirSync("static/sounds", { recursive: true });
const out = wav(renderPcm());
writeFileSync("static/sounds/ringtone.wav", out);
console.log(`Wrote static/sounds/ringtone.wav (${out.length} bytes)`);
